/* carta.css â la carta publica que se abre desde el codigo QR.
   Menu08 Â· carta, caja y produccion para food trucks.

   Solo la cargan las pantallas publicas, desde plantillas/publica.php.

   Telefono primero, y no por moda: el caso de uso es una persona de pie en la
   fila de la ventanilla, con una mano ocupada y a plena luz. De ahi salen las
   decisiones de esta hoja:

     - EL ORDEN ES EL DE LAS PREGUNTAS. Portada âÂ¿es este el truck?, Â¿esta
       abierto?â, punto âÂ¿donde?â y carta âÂ¿que hay y cuanto vale?â. La semana
       completa va plegada, porque casi nadie la pregunta.
     - CADA PRODUCTO ES UNA FICHA. El nombre y el precio se leen de un vistazo y
       la foto va a la derecha, donde el pulgar la alcanza para ampliarla.
     - LO PULSABLE MIDE 48 px. Chips, botones de contacto y fotos.

   En pantallas anchas las fichas pasan a dos columnas; el orden no cambia.

   Ni un color literal: todo sale de los tokens de md3.css, asi que el modo
   oscuro funciona sin una sola regla propia.

   Issue #17 Â· Fase 4 - Frontend */

/* 1. Marco de la pagina publica -------------------------------------------- */

.contenido-publico {
  /* El ancho se declara: body es una columna flexible y, con margen automatico
     a los lados, un hijo sin ancho se encoge a lo que mide su contenido. */
  width: 100%;
  max-width: 62rem;
  margin-inline: auto;
  padding: 0 var(--esp-4) var(--esp-8);
}

/* El atributo hidden tiene que ganar dentro de la carta: carta.js esconde con el
   fichas y categorias que traen su propio display, y una regla de autor le
   ganaria a la del navegador en los que no la marcan como !important. */
.carta [hidden] { display: none; }

/* La marca de la plataforma: una linea fina, sin quitarle la pantalla al truck. */
.carta-marca {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--esp-3);
  margin: 0;
  padding-block: var(--esp-2);
  font: var(--tipo-etiqueta-g);
}

.carta-marca a {
  display: inline-flex;
  align-items: center;
  gap: var(--esp-2);
  min-height: var(--toque);
  color: var(--on-surface-variant);
  text-decoration: none;
}

.carta-marca a:hover { color: var(--primary); }

/* 2. Portada del negocio ----------------------------------------------------

   Un cartel con los dos colores de la marca. El logotipo y el nombre comparten
   renglon; la descripcion y el contacto van debajo, a todo el ancho. */

.carta-portada {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: var(--esp-4);
  padding: var(--esp-5);
  border-radius: var(--radio-xg);
  background:
    radial-gradient(36rem 18rem at 100% 0%, color-mix(in srgb, var(--secondary) 22%, transparent), transparent 70%),
    linear-gradient(135deg, var(--primary-container), var(--secondary-container));
  color: var(--on-primary-container);
  animation: entra var(--mov-lento) both;
}

.carta-portada > * { margin-block: 0; }

.carta-logo {
  width: 88px;
  height: 88px;
  object-fit: cover;
  border: 3px solid var(--surface);
  border-radius: var(--radio-g);
  background: var(--surface);
  box-shadow: var(--elev-2);
}

/* Sin logotipo, la inicial del nombre: mejor que un hueco. */
.carta-logo-vacio {
  display: grid;
  place-items: center;
  color: var(--primary);
  font: var(--tipo-titulo-g);
  text-transform: uppercase;
}

.carta-portada-texto { display: flex; flex-direction: column; gap: var(--esp-2); min-width: 0; }

.carta-nombre {
  margin: 0;
  font-size: clamp(24px, 1rem + 3vw, 36px);
  line-height: 1.15;
  overflow-wrap: anywhere;
}

/* El estado: abierto o cerrado, con la palabra y la hora. Es lo primero que se
   quiere saber y se lee sin desplazar. */
.carta-estado {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--esp-1) var(--esp-2);
  margin: 0;
  font: var(--tipo-cuerpo-m);
}

.carta-estado-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--esp-2);
  min-height: 28px;
  padding: 0 var(--esp-3);
  border-radius: var(--radio-completo);
  font: var(--tipo-etiqueta-m);
  letter-spacing: .3px;
  white-space: nowrap;
}

.carta-estado-abierto { background: var(--degradado); color: var(--on-primary); }

/* El punto que late: es un dato vivo, de este momento. */
.carta-estado-abierto::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: var(--radio-completo);
  background: currentColor;
  --latido-tono: color-mix(in srgb, var(--on-primary) 60%, transparent);
  animation: latido 2s var(--curva-salida) infinite;
}

.carta-estado-cerrado { background: var(--surface); color: var(--on-surface); }

.carta-ciudad::before { content: "Â· "; }

.carta-acerca { grid-column: 1 / -1; display: flex; flex-direction: column; align-items: flex-start; gap: var(--esp-1); }

.carta-descripcion { margin: 0; font: var(--tipo-cuerpo-m); }

/* Tres renglones y el resto tras Â«Leer masÂ». La clase la pone carta.js: sin el,
   la descripcion sale entera. */
.carta-descripcion-corta {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  overflow: hidden;
}

.carta-leer-mas {
  min-height: 32px;
  padding: 0;
  border: none;
  background: none;
  color: var(--primary);
  font: var(--tipo-etiqueta-g);
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.carta-leer-mas:hover { background: none; color: var(--on-primary-container); }

/* El contacto son acciones, no texto: cada boton hace algo. */
.carta-acciones {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--esp-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.carta-acciones .boton { min-height: var(--toque); }

/* Sobre el cartel, el boton de contorno lleva fondo: transparente se perdia. */
.carta-acciones .boton-contorno { background: color-mix(in srgb, var(--surface) 75%, transparent); border-color: transparent; }
.carta-acciones .boton-contorno:hover { background: var(--surface); border-color: var(--primary); }

.carta-accion-texto { font: var(--tipo-cuerpo-m); }

@media (max-width: 480px) {
  .carta-portada { padding: var(--esp-4); border-radius: var(--radio-g); gap: var(--esp-3); }
  .carta-logo { width: 72px; height: 72px; }

  /* En el telefono los botones se reparten el ancho: blancos grandes. */
  .carta-acciones > li { flex: 1 1 auto; }
  .carta-acciones .boton { width: 100%; }
}

/* 3. Donde estamos ----------------------------------------------------------

   Nunca se queda vacia: sin parada abierta, dice cual es la proxima. TODO CABE
   EN 320 px: ningun renglon tiene minimo mayor que su hueco, y lo que no cabe
   salta de linea en vez de empujar la pagina. */

.carta-agenda { margin-top: var(--esp-4); }

.carta-agenda-rotulo {
  margin: 0 0 var(--esp-2);
  color: var(--on-surface-variant);
  font: var(--tipo-etiqueta-m);
  letter-spacing: .6px;
  text-transform: uppercase;
}

.carta-ahora {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--esp-3);
  padding: var(--esp-4);
  border: 1px solid color-mix(in srgb, var(--tertiary) 30%, transparent);
  border-radius: var(--radio-g);
  background: var(--degradado-suave);
  color: var(--on-tertiary-container);
}

/* Cerrado no es un error: es un horario. Va en el contenedor neutro de la
   paleta y no en el rojo, que aqui significaria que algo se rompio. */
.carta-ahora-cerrado {
  border-color: var(--outline-variant);
  background: var(--surface-container-low);
  color: var(--on-surface);
}

.carta-ahora-icono {
  display: grid;
  place-items: center;
  flex: none;
  width: 44px;
  height: 44px;
  border-radius: var(--radio-completo);
  background: color-mix(in srgb, var(--surface) 70%, transparent);
}

.carta-ahora-icono svg { width: 22px; height: 22px; }

.carta-ahora-texto { flex: 1 1 12rem; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.carta-ahora-texto > p { margin: 0; }

/* El nombre del punto, que es el dato que se busca. Se deja partir por donde
   haga falta: hay puntos con nombres largos. */
.carta-ahora-punto { font: var(--tipo-titulo-p); overflow-wrap: anywhere; }
.carta-ahora-referencia { font: var(--tipo-cuerpo-m); overflow-wrap: anywhere; }

.carta-ahora-franja { display: flex; align-items: center; gap: var(--esp-2); font: var(--tipo-cuerpo-m); }
.carta-ahora-franja svg { flex: none; width: 16px; height: 16px; }

.carta-llegar { flex: none; min-height: var(--toque); }

@media (max-width: 480px) {
  .carta-llegar { flex: 1 1 100%; }
}

/* La semana, plegada. */
.carta-semana {
  margin-top: var(--esp-2);
  border: 1px solid var(--outline-variant);
  border-radius: var(--radio-g);
  background: var(--surface);
}

.carta-semana-resumen {
  display: flex;
  align-items: center;
  gap: var(--esp-2);
  min-height: var(--toque);
  padding: 0 var(--esp-4);
  border-radius: var(--radio-g);
  color: var(--on-surface);
  font: var(--tipo-etiqueta-g);
  cursor: pointer;
  list-style: none;
  transition: background-color var(--transicion), color var(--transicion);
}

.carta-semana-resumen::-webkit-details-marker { display: none; }
.carta-semana-resumen:hover { background: var(--tinte); color: var(--primary); }
.carta-semana-resumen:focus-visible { outline: var(--foco); outline-offset: calc(var(--foco-separacion) * -1); }

.carta-semana-cuenta {
  min-width: 24px;
  padding: 0 var(--esp-2);
  border-radius: var(--radio-completo);
  background: var(--surface-container);
  color: var(--on-surface-variant);
  font: var(--tipo-etiqueta-m);
  line-height: 24px;
  text-align: center;
}

.carta-semana-flecha { width: 20px; height: 20px; margin-left: auto; transition: transform var(--mov-medio); }
.carta-semana[open] .carta-semana-flecha { transform: rotate(180deg); }

.carta-paradas { list-style: none; margin: 0; padding: 0 var(--esp-2) var(--esp-2); }

/* Un renglon por parada: dia, punto y franja. El punto es el unico que crece y
   el unico que puede saltar de linea. */
.carta-parada {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--esp-2);
  padding: var(--esp-2);
  border-top: 1px solid var(--outline-variant);
}

/* Las paradas de hoy, senaladas: con la palabra Â«HoyÂ» y con el tinte. */
.carta-parada-hoy { border-radius: var(--radio-p); background: var(--tinte); }
.carta-parada-hoy .carta-parada-dia { color: var(--primary); }

/* El dia, en una caja de ancho fijo: asi la columna de puntos arranca siempre
   en la misma linea vertical y la lista se lee de un barrido. */
.carta-parada-dia { flex: none; min-width: 2.5rem; color: var(--on-surface-variant); font: var(--tipo-etiqueta-g); }
.carta-parada-punto { flex: 1 1 8rem; min-width: 0; overflow-wrap: anywhere; }

.carta-parada-horario {
  flex: none;
  margin-left: auto;
  color: var(--on-surface-variant);
  font: var(--tipo-cuerpo-m);
  white-space: nowrap;
}

/* 4. Buscador y barra de categorias ----------------------------------------- */

.carta-herramientas { margin-top: var(--esp-5); }

.carta-buscador { position: relative; margin-bottom: var(--esp-2); }

.carta-buscador-icono {
  position: absolute;
  left: var(--esp-4);
  top: 50%;
  width: 20px;
  height: 20px;
  margin-top: -10px;
  color: var(--on-surface-variant);
  pointer-events: none;
}

.carta-buscador-campo {
  width: 100%;
  height: var(--toque);
  padding: 0 var(--esp-4) 0 44px;
  border: 1px solid var(--outline-variant);
  border-radius: var(--radio-completo);
  background: var(--surface);
  color: var(--on-surface);
  font: var(--tipo-cuerpo-g);
  box-shadow: var(--elev-1);
  transition: border-color var(--transicion), box-shadow var(--transicion);
}

.carta-buscador-campo:hover { border-color: var(--outline); }

.carta-buscador-campo:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 4px var(--tinte-fuerte);
}

/* La barra se queda pegada arriba al desplazar: en una carta de cinco
   categorias, volver al principio para cambiar de bloque es justo lo que no se
   puede pedir a quien esta en la fila.

   El scroll horizontal es de la barra, nunca del documento. */
.carta-barra {
  position: sticky;
  top: 0;
  z-index: 5;
  margin-inline: calc(var(--esp-4) * -1);
  padding: var(--esp-2) var(--esp-4);
  /* Translucida y con desenfoque: los productos pasan por debajo y se intuyen,
     asi que la barra se lee como algo que flota sobre la carta. */
  background: color-mix(in srgb, var(--surface) 88%, transparent);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--outline-variant);
  overflow-x: auto;
  overscroll-behavior-x: contain;
  /* Fina, no escondida: con raton, la barra de desplazamiento es la unica pista
     de que hay mas categorias a la derecha. */
  scrollbar-width: thin;
}

.carta-barra ul {
  display: flex;
  gap: var(--esp-2);
  list-style: none;
  margin: 0;
  padding: 0;
  width: max-content;
}

.carta-barra a {
  display: inline-flex;
  align-items: center;
  gap: var(--esp-2);
  /* 48 px: el minimo de toque del proyecto, por encima de los 44 de WCAG. */
  min-height: var(--toque);
  padding: 0 var(--esp-4);
  border: 1px solid var(--outline-variant);
  border-radius: var(--radio-completo);
  background: var(--surface);
  color: var(--on-surface);
  font: var(--tipo-etiqueta-g);
  text-decoration: none;
  white-space: nowrap;
  transition: background-color var(--transicion), color var(--transicion),
              border-color var(--transicion), box-shadow var(--transicion), transform var(--transicion);
}

/* Cuantos productos hay en cada bloque: se sabe antes de saltar. */
.carta-barra-cuenta {
  min-width: 22px;
  padding: 0 6px;
  border-radius: var(--radio-completo);
  background: var(--surface-container);
  color: var(--on-surface-variant);
  font: var(--tipo-etiqueta-m);
  line-height: 22px;
  text-align: center;
  transition: background-color var(--transicion), color var(--transicion);
}

.carta-barra a:hover { background: var(--tinte); color: var(--primary); border-color: var(--primary); }
.carta-barra a:focus-visible { outline: var(--foco); outline-offset: calc(var(--foco-separacion) * -1); }

@media (prefers-reduced-motion: no-preference) {
  .carta-barra a:active { transform: scale(.96); }
}

/* La categoria que se esta leyendo. La marca interfaz.js al desplazar; sin
   JavaScript la barra sigue navegando igual, solo que sin resaltar. */
.carta-barra a[aria-current="true"] {
  background: var(--degradado);
  color: var(--on-primary);
  border-color: var(--primary);
  box-shadow: var(--elev-realce);
}

.carta-barra a[aria-current="true"] .carta-barra-cuenta {
  background: color-mix(in srgb, var(--on-primary) 22%, transparent);
  color: var(--on-primary);
}

.carta-sin-resultados {
  margin: var(--esp-6) 0;
  color: var(--on-surface-variant);
  text-align: center;
}

/* 5. Bloques de categoria y fichas de producto ------------------------------ */

.carta-categoria {
  /* La barra pegada arriba taparia el titulo al saltar al ancla. */
  scroll-margin-top: calc(var(--toque) + var(--esp-5));
}

.carta-categoria h2 {
  display: flex;
  align-items: center;
  gap: var(--esp-3);
  margin-block: var(--esp-5) var(--esp-3);
}

.carta-categoria h2::before {
  content: "";
  flex: none;
  width: 4px;
  height: 1.1em;
  border-radius: var(--radio-completo);
  background: linear-gradient(var(--primary), var(--secondary));
}

/* minmax(0, 1fr): sin el minimo en cero, una descripcion larga estira la
   columna y saca la barra horizontal del documento entero. */
.carta-lista {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--esp-3);
  list-style: none;
  margin: 0;
  padding: 0;
}

@media (min-width: 768px) {
  .carta-lista { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--esp-4); }
}

/* La ficha. El texto a la izquierda, que es lo que se lee, y la foto a la
   derecha, donde cae el pulgar para ampliarla. El precio va abajo y en el color
   de la marca: es el dato que se compara de ficha en ficha, y asi queda siempre
   en el mismo sitio. */
.carta-item {
  display: flex;
  align-items: stretch;
  justify-content: space-between;
  gap: var(--esp-3);
  padding: var(--esp-3);
  border: 1px solid var(--outline-variant);
  border-radius: var(--radio-g);
  background: var(--surface);
  box-shadow: var(--elev-1);
  transition: border-color var(--transicion), box-shadow var(--mov-medio);
}

@media (hover: hover) {
  .carta-item:hover { border-color: var(--anillo); box-shadow: var(--elev-2); }
}

.carta-texto { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: var(--esp-1); }

.carta-texto h3 { margin: 0; font-size: 16px; line-height: 22px; font-weight: 600; overflow-wrap: anywhere; }

/* 14 px es el suelo que fija el issue: por debajo no se lee de pie y con sol.
   Tres renglones como mucho: la ficha no crece sin limite y todas se parecen.
   La descripcion entera se lee en el visor, al tocar la foto. */
.carta-texto p {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  overflow: hidden;
  margin: 0;
  color: var(--on-surface-variant);
  font: var(--tipo-cuerpo-m);
}

/* El pie de la ficha se va al fondo: con descripciones de distinto largo, el
   precio queda alineado de una ficha a la de al lado. */
.carta-pie { display: flex; flex-wrap: wrap; align-items: center; gap: var(--esp-2); margin-top: auto; padding-top: var(--esp-2); }

.carta-precio { color: var(--primary); font-size: 17px; line-height: 24px; font-weight: 700; white-space: nowrap; }

.carta-foto {
  display: block;
  flex: none;
  width: 96px;
  height: 96px;
  object-fit: cover;
  border-radius: var(--radio-m);
  transition: transform var(--mov-lento);
}

/* La foto es un enlace: se amplia al tocarla. El marco recorta el acercamiento
   y lleva el anillo de foco. */
.carta-foto-enlace {
  position: relative;
  display: block;
  flex: none;
  align-self: flex-start;
  border-radius: var(--radio-m);
  overflow: hidden;
  box-shadow: var(--elev-1);
}

.carta-foto-enlace:focus-visible { outline: var(--foco); outline-offset: var(--foco-separacion); }

@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .carta-foto-enlace:hover .carta-foto { transform: scale(1.08); }
}

/* Reemplazo del producto sin foto: mismo hueco, para que las fichas no bailen. */
.carta-foto-vacia {
  display: grid;
  place-items: center;
  align-self: flex-start;
  background: var(--surface-container);
  color: var(--outline);
}

.carta-foto-vacia svg { width: 36%; height: 36%; }

@media (min-width: 768px) {
  .carta-item { padding: var(--esp-4); }
  .carta-foto { width: 112px; height: 112px; }
}

/* 6. Producto agotado -------------------------------------------------------

   Se atenua, pero se queda: saber que hoy no hay chunchullo es informacion util
   antes de llegar a la ventanilla. La atenuacion no decide sola âla ficha lleva
   ademas la etiqueta Â«No disponibleÂ»â. */

.carta-item-agotado { background: var(--surface-container-low); box-shadow: none; }

.carta-item-agotado .carta-foto { opacity: .5; filter: grayscale(.6); }

.carta-item-agotado .carta-texto h3,
.carta-item-agotado .carta-texto p,
.carta-item-agotado .carta-precio { color: color-mix(in srgb, var(--on-surface) 50%, transparent); }

/* 7. Cierre y visor de fotos ------------------------------------------------ */

.carta-cierre { margin-top: var(--esp-7); text-align: center; font: var(--tipo-cuerpo-m); }

.carta-cierre a {
  display: inline-flex;
  align-items: center;
  gap: var(--esp-2);
  min-height: var(--toque);
  color: var(--on-surface-variant);
  text-decoration: none;
}

.carta-cierre a:hover { color: var(--primary); }

/* El visor: la foto en grande, con el nombre, el precio y la descripcion
   entera. <dialog> nativo: encierra el foco y atiende Escape. */
.carta-visor {
  width: min(30rem, calc(100vw - var(--esp-5)));
  max-height: calc(100vh - var(--esp-5));
  max-height: calc(100dvh - var(--esp-5));
  padding: 0;
  border: none;
  border-radius: var(--radio-xg);
  background: var(--surface);
  color: var(--on-surface);
  box-shadow: var(--elev-3);
  overflow: auto;
}

.carta-visor[open] { animation: emerge var(--mov-medio) both; }

.carta-visor::backdrop {
  background: var(--velo);
  -webkit-backdrop-filter: blur(3px);
  backdrop-filter: blur(3px);
  animation: aparece .2s var(--curva) both;
}

.carta-visor-cerrar { position: absolute; top: var(--esp-2); right: var(--esp-2); z-index: 1; margin: 0; }

.carta-visor-cerrar .boton-simbolo {
  background: color-mix(in srgb, var(--surface) 88%, transparent);
  box-shadow: var(--elev-1);
}

.carta-visor-cerrar .boton-simbolo:hover { background: var(--surface); }

.carta-visor-foto { display: block; width: 100%; aspect-ratio: 4 / 3; object-fit: cover; border-radius: 0; background: var(--surface-container); }

.carta-visor-texto { display: flex; flex-direction: column; gap: var(--esp-2); padding: var(--esp-4) var(--esp-5) var(--esp-5); }

.carta-visor-fila { display: flex; align-items: baseline; justify-content: space-between; gap: var(--esp-3); }

.carta-visor-nombre { margin: 0; font: var(--tipo-titulo-p); overflow-wrap: anywhere; }

.carta-visor-descripcion { margin: 0; color: var(--on-surface-variant); }
.carta-visor-descripcion:empty { display: none; }

/* carta.js â las mejoras de la carta publica.
   Menu08 Â· carta, caja y produccion para food trucks.

   Solo la carga /carta/{slug}, a traves del parametro $guiones.

   TRES COSAS, Y LAS TRES SON MEJORA PROGRESIVA. La carta se lee entera sin este
   archivo: las categorias son anclas, la foto es un enlace a la imagen y la
   descripcion sale completa. Lo que se pone encima:

     - El buscador. Filtra las fichas YA pintadas por el servidor: no hay ninguna
       consulta de por medio, asi que responde en cada tecla y no gasta datos
       del telefono del que esta en la fila.
     - El visor de fotos. La foto se abre en grande sin salir de la carta.
     - Â«Leer masÂ». La descripcion del negocio se recorta a tres renglones, y el
       boton solo aparece si de verdad no cabe.

   Las tres piezas salen del servidor con hidden o sin recortar, y es este
   archivo el que las enciende: sin el no prometen nada que no hagan.

   Issue #17 Â· Fase 4 - Frontend */

'use strict';

(function () {
    var raiz = document.querySelector('[data-carta]');

    if (raiz === null) {
        return;
    }

    /* ------------------------------------------------------------ leer mas */

    (function leerMas() {
        var texto = raiz.querySelector('[data-carta-descripcion]');
        var boton = raiz.querySelector('[data-carta-leer-mas]');

        if (texto === null || boton === null) {
            return;
        }

        texto.classList.add('carta-descripcion-corta');

        /* Si con el recorte puesto el texto cabe entero, el boton sobra: no se
           ofrece Â«leer masÂ» de algo que ya se esta leyendo completo. */
        if (texto.scrollHeight <= texto.clientHeight + 1) {
            texto.classList.remove('carta-descripcion-corta');

            return;
        }

        boton.hidden = false;

        boton.addEventListener('click', function () {
            var abierto = boton.getAttribute('aria-expanded') === 'true';

            texto.classList.toggle('carta-descripcion-corta', abierto);
            boton.setAttribute('aria-expanded', abierto ? 'false' : 'true');
            boton.textContent = abierto ? 'Leer mÃ¡s' : 'Leer menos';
        });
    }());

    /* ------------------------------------------------------------ buscador */

    /** Sin tildes y en minusculas: quien busca Â«limonÂ» encuentra Â«LimÃ³nÂ». */
    function normalizar(texto) {
        var s = String(texto || '').toLowerCase();

        return typeof s.normalize === 'function'
            ? s.normalize('NFD').replace(/[Ì-Í¯]/g, '')
            : s;
    }

    (function buscador() {
        var caja = raiz.querySelector('[data-carta-buscador]');
        var campo = raiz.querySelector('[data-carta-busqueda]');
        var sinResultados = raiz.querySelector('[data-carta-sin-resultados]');
        var categorias = raiz.querySelectorAll('[data-carta-categoria]');

        if (caja === null || campo === null || categorias.length === 0) {
            return;
        }

        /* El texto de cada ficha se normaliza una vez, no en cada tecla. */
        var bloques = [];
        var i;

        for (i = 0; i < categorias.length; i += 1) {
            var nodos = categorias[i].querySelectorAll('[data-carta-producto]');
            var fichas = [];
            var j;

            for (j = 0; j < nodos.length; j += 1) {
                fichas.push({
                    nodo: nodos[j],
                    texto: normalizar(
                        (nodos[j].getAttribute('data-nombre') || '') + ' '
                        + (nodos[j].getAttribute('data-descripcion') || '')
                    )
                });
            }

            bloques.push({ nodo: categorias[i], fichas: fichas });
        }

        function filtrar() {
            var consulta = normalizar(campo.value).trim();
            var visibles = 0;
            var b;
            var f;

            for (b = 0; b < bloques.length; b += 1) {
                var enBloque = 0;

                for (f = 0; f < bloques[b].fichas.length; f += 1) {
                    var ficha = bloques[b].fichas[f];
                    var coincide = consulta === '' || ficha.texto.indexOf(consulta) !== -1;

                    ficha.nodo.hidden = !coincide;

                    if (coincide) {
                        enBloque += 1;
                    }
                }

                /* Un titulo de categoria sin ninguna ficha debajo es ruido. */
                bloques[b].nodo.hidden = enBloque === 0;
                visibles += enBloque;
            }

            if (sinResultados !== null) {
                sinResultados.hidden = visibles > 0;
            }
        }

        caja.hidden = false;
        campo.addEventListener('input', filtrar);

        /* Escape limpia la busqueda y devuelve la carta entera. */
        campo.addEventListener('keydown', function (e) {
            if (e.key === 'Escape' && campo.value !== '') {
                e.preventDefault();
                campo.value = '';
                filtrar();
            }
        });

        /* El navegador puede restaurar el texto del campo al volver atras. */
        filtrar();
    }());

    /* ------------------------------------------------------- visor de foto */

    (function visor() {
        var dialogo = raiz.querySelector('[data-carta-visor]');

        /* Sin <dialog> la foto sigue siendo un enlace a la imagen. */
        if (dialogo === null || typeof dialogo.showModal !== 'function') {
            return;
        }

        var foto = dialogo.querySelector('[data-carta-visor-foto]');
        var nombre = dialogo.querySelector('[data-carta-visor-nombre]');
        var precio = dialogo.querySelector('[data-carta-visor-precio]');
        var descripcion = dialogo.querySelector('[data-carta-visor-descripcion]');

        raiz.addEventListener('click', function (e) {
            var enlace = e.target.closest ? e.target.closest('[data-carta-ver]') : null;

            if (enlace === null) {
                return;
            }

            var ficha = enlace.closest('[data-carta-producto]');

            if (ficha === null) {
                return;
            }

            e.preventDefault();

            /* Todo con textContent y con atributos: lo que escribe el dueno del
               truck nunca se inserta como HTML. */
            foto.src = enlace.getAttribute('href');
            foto.alt = ficha.getAttribute('data-nombre') || '';
            nombre.textContent = ficha.getAttribute('data-nombre') || '';
            precio.textContent = ficha.getAttribute('data-precio') || '';
            descripcion.textContent = ficha.getAttribute('data-descripcion') || '';

            dialogo.showModal();
        });

        /* Un toque fuera de la caja cierra: el velo es el propio <dialog>, asi
           que el clic le llega a el y no a lo de dentro. */
        dialogo.addEventListener('click', function (e) {
            if (e.target === dialogo) {
                dialogo.close();
            }
        });
    }());
}());
